    "explanation": "Choice C is correct. It's given that admission to the museum will cost $8.50 for each student and $12 for each chaperone. It's also given that it\nwill cost a total of $730 for admission to the museum for all 83 people on the field trip. Let & represent the number of students and y represent\nthe number of chaperones going on the field trip. Since there are a total of 83 people going on the field trip, it follows that & + ¢ = 83. Since\nadmission to the museum for each student costs $8.50 and each chaperone costs $12, the total cost can be represented by the equation 8.50\n+ 12y = 730. The equations x + y = 83 and 8.50z + 12y = 730 form a system of equations. Subtracting z from both sides of the equation\n+ y = 83yields y = 83 — x. Substituting 83 — for yin the equation 8.50z + 12y = 730 yields 8.50z + 12(83 — x) = 730, or —3.50z\n+ 996 = 730. Subtracting 996 from both sides of this equation yields —3.50z = —266. Dividing both sides of this equation by —3.50 yields =\n= 76. Therefore, 76 students are going on the field trip.\nChoice A is incorrect and may result from conceptual or calculation errors.\nChoice B is incorrect and may result from conceptual or calculation errors.\nChoice D is incorrect and may result from conceptual or calculation errors.",
